/**
 * The ThemisIQ wordmark, embedded as base64 PNG for jsPDF to place on generated documents.
 *
 * =====================================================================
 * ⚠️ THIS IS THE ARTEFACT. IT IS NOT TO BE RECREATED.
 * =====================================================================
 * These bytes ARE the wordmark — not a description of it, not an approximation, and not something
 * to be regenerated from a font and a colour. Do not redraw it in vector primitives, do not trace
 * it, do not substitute a text rendering of "ThemisIQ" because the image was inconvenient to load,
 * and do not swap in a differently-cropped export. A mark that is nearly right is wrong: it appears
 * on documents customers send to verifiers and auditors, and it is the only thing on the page that
 * identifies who produced them.
 *
 * If it must be replaced, replace it with a new export of the SAME artwork, and update the pixel
 * dimensions below in the same change.
 *
 * =====================================================================
 * THE BYTES
 * =====================================================================
 * PNG, 730×182 pixels, 8-bit RGBA (colour type 6), 50,779 bytes decoded.
 *
 * ⚠️ RGBA MATTERS: the mark has a transparent background, so it sits on the cover's paper colour
 * rather than carrying a white box of its own. Flattening it onto white would show as a pale
 * rectangle on the #f8f7f5 cover.
 *
 * ⚠️ THE ASPECT RATIO IS 4.0110 (730/182). Place it by setting ONE dimension and deriving the
 * other from WORDMARK_ASPECT — passing an independent width and height to addImage stretches the
 * mark, and a stretched wordmark is the most visible way to look careless on a formal document.
 *
 * To regenerate the constant from a new PNG:
 *
 *   base64 -i wordmark.png | tr -d '\n' > logo.b64
 *
 * The newline stripping is not cosmetic — see the same note in lib/fonts/charis.ts.
 */

/** Raw base64 of the PNG. One line, never wrapped. */
export const THEMISIQ_WORDMARK_PNG_B64 =
  ''

/** Intrinsic pixel width of the artwork. */
export const WORDMARK_WIDTH_PX = 730

/** Intrinsic pixel height of the artwork. */
export const WORDMARK_HEIGHT_PX = 182

/** width / height. Derive the dimension you do not set, so the mark is never stretched. */
export const WORDMARK_ASPECT = WORDMARK_WIDTH_PX / WORDMARK_HEIGHT_PX

/**
 * The form jsPDF's addImage takes directly:
 *   doc.addImage(THEMISIQ_WORDMARK_DATA_URI, 'PNG', x, y, w, w / WORDMARK_ASPECT)
 */
export const THEMISIQ_WORDMARK_DATA_URI =
  `data:image/png;base64,${THEMISIQ_WORDMARK_PNG_B64}`
